#!/bin/bash
# Uninstall script for Chrome Remote Desktop
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Chrome Remote Desktop..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Chrome Remote Desktop if running..."
pkill -f "Chrome Remote Desktop" 2>/dev/null || true

# Unload service org.chromium.chromoting
echo "Unloading service org.chromium.chromoting..."
launchctl unload -w /Library/LaunchAgents/org.chromium.chromoting.plist 2>/dev/null || true
launchctl unload -w /Library/LaunchDaemons/org.chromium.chromoting.plist 2>/dev/null || true
launchctl unload -w ~/Library/LaunchAgents/org.chromium.chromoting.plist 2>/dev/null || true

# Remove $HOME/Library/Saved Application State/com.google.chromeremotedesktop.me2me-host-uninstaller.savedState
echo "Removing $HOME/Library/Saved Application State/com.google.chromeremotedesktop.me2me-host-uninstaller.savedState..."
if [ -d "$HOME/Library/Saved Application State/com.google.chromeremotedesktop.me2me-host-uninstaller.savedState" ]; then
    rm -rf "$HOME/Library/Saved Application State/com.google.chromeremotedesktop.me2me-host-uninstaller.savedState" 2>/dev/null || true
elif [ -f "$HOME/Library/Saved Application State/com.google.chromeremotedesktop.me2me-host-uninstaller.savedState" ]; then
    rm -f "$HOME/Library/Saved Application State/com.google.chromeremotedesktop.me2me-host-uninstaller.savedState" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
